357	  private static appendAndTruncate(
358	    currentBuffer: string,
359	    chunk: string,
360	    maxSize: number,
361	  ): { newBuffer: string; truncated: boolean } {
362	    const chunkLength = chunk.length;
363	    const currentLength = currentBuffer.length;
364	    const newTotalLength = currentLength + chunkLength;
365	
366	    if (newTotalLength <= maxSize) {
367	      return { newBuffer: currentBuffer + chunk, truncated: false };
368	    }
369	
370	    // Truncation is needed.
371	    if (chunkLength >= maxSize) {
372	      // The new chunk is larger than or equal to the max buffer size.
373	      // The new buffer will be the tail of the new chunk.
374	      return {
375	        newBuffer: chunk.substring(chunkLength - maxSize),
376	        truncated: true,
377	      };
378	    }
379	
380	    // The combined buffer exceeds the max size, but the new chunk is smaller than it.
381	    // We need to truncate the current buffer from the beginning to make space.
382	    const charsToTrim = newTotalLength - maxSize;
383	    const truncatedBuffer = currentBuffer.substring(charsToTrim);
384	    return { newBuffer: truncatedBuffer + chunk, truncated: true };
385	  }
